importScripts("../standard-file-js/sfjs.umd.js");const{SFItem,SFItemParams,SFJS}=self.StandardFileJs;async function uploadFile(e,t,a){const r=a.content.relayUrl.replace("filesafe.standardnotes.org","filesafe.standardnotes.com"),s=await fetch(`${r}/integrations/save-item`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({file:{name:e,item:t},source:a.content.source,authorization:a.content.authorization})}),n=await s.json();if(!s.ok||n.error)throw n.error||new Error("FileSafe upload failed.");return n.metadata}self.addEventListener("message",async e=>{const t=e.data;try{if("encrypt"===t.operation){const e=new SFItem({content_type:t.contentType,content:{rawData:t.fileData,fileName:t.fileName,fileType:t.fileType}}),a=await new SFItemParams(e,t.keys,t.authParams).paramsForSync();self.postMessage({fileItem:a})}else if("decrypt"===t.operation){await SFJS.itemTransformer.decryptItem(t.item,t.keys);const e=new SFItem(t.item);if(e.errorDecrypting)throw new Error("Error decrypting Standard Notes file.");self.postMessage({decryptedData:e.content.rawData,decryptedItem:e})}else if("upload"===t.operation){const e=await uploadFile(t.outputFileName,t.fileItem,t.integration);self.postMessage({metadata:e})}}catch(e){self.postMessage({error:{message:e.message||String(e)}})}});